def flatten_once(items):
    out = []
    for item in items:
        if isinstance(item, (list, tuple)):
            out.extend(item)
        else:
            out.append(item)
    return out

def is_palindrome_text(text):
    filtered_chars = [char.lower() for char in text if char.isalnum()]
    return filtered_chars == filtered_chars[::-1]

def safe_divide(a, b, default=None):
    if b == 0:
        return default
    return a / b

def normalize_whitespace(text):
    import re
    # Replace all sequences of whitespace characters with a single space
    collapsed = re.sub(r'\s+', ' ', text)
    # Trim leading and trailing whitespace
    return collapsed.strip()

def first_non_none(values, default=None):
    for val in values:
        if val is not None:
            return val
    return default

def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i + 1 < len(s) and values[s[i]] < values[s[i+1]]:
            total -= values[s[i]]
        else:
            total += values[s[i]]
    return total

def is_valid_parentheses(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def grade_bucket(score):
    if score >= 90:
        return 'A'
    if score >= 80:
        return 'B'
    if score >= 70:
        return 'C'
    if score >= 60:
        return 'D'
    return 'F'
